dataModel:
public enum XpSource { Use, Fight, Study, Ward }
public sealed record SkillDef(string Key, string Name, string ArtKey);
public sealed record TraitTier(int Tier, int Points, IReadOnlyDictionary<string, float> Fx);
public sealed record TraitDef(string Key, string Name, TraitTier[] Tiers, string[] Excludes);
public sealed class SkillState { public int Level; public float Xp; public int Floor; public int LastUsedDay;
  public Dictionary<XpSource, float> Today = new(); }
public static class XpCurve { public static float Need(int l) => 40f + 0.32f * l * l * l; }

public sealed record MoodFactorDef(string Key, string Label, float Value, int Days, bool Stacks);
public sealed class MoodFactor { public string Key; public float Value; public int DaysLeft; public int? SourceId; }
public sealed class MoraleState { public List<MoodFactor> Factors = new(); public int LowDays; public int CooldownUntil; }
public enum BreakKind { RunOff, Attack, Suicide, Arson, WreckStores, WalkIntoDead, DriveOff, ShutDown }
public sealed record MentalBreak(int SurvivorId, BreakKind Kind, int? VictimId) : IDomainEvent;

public readonly record struct PairKey(int Lo, int Hi) { public static PairKey Of(int a, int b) => a < b ? new(a, b) : new(b, a); }
public sealed class PairState { public float Opinion; public float History; public bool Partners;
  public List<(string Reason, float Amount)> Why = new(); }
public enum BondLevel { Rival, Disliked, Neutral, Friendly, Friend, CloseFriend, Partner }
public sealed record BondChanged(PairKey Pair, BondLevel From, BondLevel To, string Reason) : IDomainEvent;

public enum LifeStage { Baby, Child, Youth, Adult }
public sealed record RecruitArchetypeDef(string Key, int Min, int Max, string SkillTable, string GearTable);
public sealed class PendingArrival { public int[] SurvivorIds; public int BaseId; public int ArriveDay; public bool Lost; }
public sealed class FamilyState { public int? PartnerId; public int? ExpectingDue; public int[] ChildIds = []; }
public sealed record SurvivorJoined(int SurvivorId, int BaseId, string Via) : IDomainEvent;
public sealed record SurvivorDeserted(int SurvivorId, int BaseId, string[] Took) : IDomainEvent;

public sealed record MedBlock(int Tier, int Beds, int MedicsNeeded, float HealMult, float Teach, int WardCap);
public sealed record TreatmentDef(string Key, int Meds, int MedicCost, int MinSkill, int Xp);
public sealed class BaseMedSettings { public int AdmitBelow = 70; public int MedsReserve = 2; public bool AutoTreat = true; }
public sealed record Treated(int PatientId, int MedicId, string Treatment, int BaseId) : IDomainEvent;

public sealed record ConditionDef(string Key, string Name, float HpAt100, float WorkMult, float Drift,
  float Contagion, string? TurnsInto, int MinCourse, bool Rests);
public sealed class Condition { public string Key; public float Severity; public int DosesLeft; public bool Mending; }
public interface IExposure { float RawWaterShare(int survivorId); float RawMeatShare(int survivorId); float TileInfection(int baseId); }
public sealed record SurvivorTurned(int SurvivorId, int BaseId) : IDomainEvent;

public enum Ground : byte { Grass, Dirt, Road, Paved, Soil, Water, Rock }
public readonly record struct Cell(int X, int Y); // relative to base centre
public sealed record Footprint(int W, int H, bool SoilOnly, Cell[] Indoor);
public sealed class BaseMap { public int Size = 500; public int YardHalf = 38; public Ground[] Ground; public sbyte[] Height;
  public Dictionary<Cell, int> Occupant = new(); public HashSet<Cell> Cleared = new(); public int Seed; }
public sealed record PlaceBuilding(int BaseId, string DefKey, Cell At, int Rot) : ICommand;

public abstract record FurnitureUse;
public sealed record BedUse(int Sleepers, float Mood) : FurnitureUse;
public sealed record StorageUse(int Kg) : FurnitureUse;
public sealed record ComfortUse(float Mood) : FurnitureUse;
public sealed class PlacedPiece { public int Id; public int HostBuildingId; public Cell At; public int Rot; public ItemInstance Item; }

public enum BaseTier { Camp = 0, Shelter = 1, Outpost = 2, Hub = 3 }
public sealed record TierDef(BaseTier Tier, int Yard, int CoreKg, string? StepUpBuilding);
public sealed record TentDef(string Key, int Sleepers, int StorageKg, int PitchMinutes, string BagItem);
public sealed record SetUpCamp(int PartyId, Cell Spot) : ICommand;
public sealed record BaseTierChanged(int BaseId, BaseTier From, BaseTier To) : IDomainEvent;

public sealed record FoodDef(string Key, int Kcal, float Kg, int ShelfDays, bool Cold, bool Raw, string[] Tags);
public sealed class FoodLot { public string Food; public int Qty; public float DaysLeft; public bool Eggs; public float Poison; public int? CookId; }
public sealed record CookRecipeDef(string Key, string Station, (string Tag, int Qty)[] In, string Out, int OutQty, float Hours, int MinSkill);
public interface IFoodSource { int KcalAvailable(); IReadOnlyList<FoodLot> TakeKcal(int kcal); }

public sealed record CropDef(string Key, int Days, float Yield, int Seed, float Water, Season[] Seasons, int HarvestWindow, string Food);
public sealed class CropPlot { public int PlacedId; public string? Crop; public float Growth; public float CareSum; public int Days; }
public sealed class LandState { public float Level = 1f; public int LastHour; }
public static class Regrow { public static float Level(float l, int hours, float halfLifeDays) => 1 - (1 - l) * MathF.Pow(0.5f, hours / (24f * halfLifeDays)); }

public sealed record WaterSourceDef(float RawPerDay, float RainMult, bool CarriesEggs);
public sealed record PurifierDef(string Kind, float PerDay, float PerHeadFuel, string FuelKey);
public sealed class WaterDay { public float Drunk; public float RawDrunk; public Dictionary<int, float> RawShare = new(); }

public enum BillMode { Forever, UntilN, KeepN, Off }
