  public float Battery; public HashSet<int> PoweredNow = new(); }
public interface IPower { bool IsPowered(int buildingId); }

public enum HaulMode { Send, Stock }
public sealed record HaulOrder(int Id, int From, int To, string What, HaulMode Mode, int Qty);
