public sealed record SupplyRunTemplate(int Id, int From, int To, int[] Crew, int? VehicleId, Dictionary<string,int> Deliver, int EveryDays);

public sealed record FixtureDef(float UseWear, string[] WeatherTags, float RepairHours, int Parts);
