public sealed record RepairOrder(int BaseId, int BuildingId, int? SurvivorId) : ICommand;
public sealed record FixtureBroke(int BaseId, int BuildingId) : IDomainEvent;

public sealed record EffectDef(string Op, string Target, float Amount, string? Key = null);
public sealed record OptionDef(string Text, EffectDef[] Effects, float AiHint);
public sealed record HubEventDef(string Key, float Weight, string[] Seasons, ConditionDef[] Needs, OptionDef[] Options);
public sealed class HubEventState { public int LastDay = -99; public int? PendingCardId; }
public interface IEffectRunner { string Preview(EffectDef e, CardContext c); void Apply(EffectDef e, CardContext c); }

public interface IWorkType { string Key { get; } string Skill { get; } bool HasWork(Base b, int hour); int Capacity(Base b); }
public enum Slot : byte { Work = (byte)'w', Guard = (byte)'g', Free = (byte)'f', Sleep = (byte)'s' }
public sealed class Role { public int Id; public string Name; public Dictionary<string, int> Pri = new();
  public Dictionary<string, int> Min = new(); public string Sched = new string('w', 24); }
public sealed class WorkAssign { public int? RoleId; public Dictionary<string, int> Over = new(); }
